function audit(){const old=inherited(()=>base.audit()),issues=[...(old.issues||[])];for(const r of rows){const t=topics.find(x=>x.key===r.key);if(!t||t.label!==r.label||t.specificGuidance!==true||t.termResolution!==false||!refs.every(k=>sources[k]))issues.push('tinea-neuro-infections:'+r.key);}return {...old,ok:!issues.length,issues,topics:topics.length};}
